use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::{collections::HashMap, fs, path::PathBuf};
use tauri::Emitter;
use rusqlite::{params, Connection, OptionalExtension};

use crate::{chat, ensure_engine, inkling_render, list_saved_meetings, stream_json, AppState, ChatTurn};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PersonDetails {
    #[serde(rename = "includeInBrain", default = "default_true")] pub include_in_brain: bool,
    #[serde(default)] pub likes: Vec<String>,
    #[serde(default)] pub dislikes: Vec<String>,
    #[serde(rename = "familyNames", default)] pub family_names: Vec<String>,
    #[serde(rename = "importantDates", default)] pub important_dates: Vec<String>,
    #[serde(rename = "giftIdeas", default)] pub gift_ideas: Vec<String>,
    #[serde(default)] pub learned: Vec<LearnedDetail>,
    #[serde(default)] pub notes: Option<String>,
}
fn default_true() -> bool { true }
impl Default for PersonDetails { fn default() -> Self { Self { include_in_brain: true, likes: vec![], dislikes: vec![], family_names: vec![], important_dates: vec![], gift_ideas: vec![], learned: vec![], notes: None } } }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LearnedDetail { pub category: String, pub value: String, #[serde(default)] pub learned: bool, #[serde(rename = "sourceEpisodeID", default)] pub source_episode_id: Option<String> }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BrainPerson { pub id: i64, pub kind: String, pub name: String, pub world: String, pub summary: String, #[serde(rename = "createdAt")] pub created_at: String, #[serde(rename = "updatedAt")] pub updated_at: String, pub forgotten: bool, #[serde(rename = "closenessLevel", skip_serializing_if = "Option::is_none")] pub closeness_level: Option<i64> }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrbitEntry { pub entity: BrainPerson, #[serde(rename = "meetingCount")] pub meeting_count: i64, #[serde(rename = "lastMet", skip_serializing_if = "Option::is_none")] pub last_met: Option<String>, #[serde(rename = "hasOpenPromise")] pub has_open_promise: bool, #[serde(rename = "hasChanged")] pub has_changed: bool, #[serde(rename = "closenessLevel", skip_serializing_if = "Option::is_none")] pub closeness_level: Option<i64>, #[serde(rename = "suggestedClosenessLevel")] pub suggested_closeness_level: i64 }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PersonPage { pub entity: BrainPerson, pub details: PersonDetails, pub meetings: Vec<PersonMeeting>, #[serde(rename = "openCommitmentsByPerson")] pub open_commitments_by_person: Vec<BrainFact>, #[serde(rename = "openCommitmentsToPerson")] pub open_commitments_to_person: Vec<BrainFact>, pub facts: Vec<BrainFact> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PersonMeeting { pub id: String, #[serde(rename = "meetingFolder")] pub meeting_folder: String, #[serde(rename = "startedAt")] pub started_at: String, #[serde(rename = "processedAt", skip_serializing_if = "Option::is_none")] pub processed_at: Option<String>, pub model: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BrainFact { pub id: i64, pub kind: String, pub predicate: String, pub value: String, pub due: Option<String>, pub done: bool, #[serde(rename = "validFrom")] pub valid_from: String, #[serde(rename = "invalidatedAt")] pub invalidated_at: Option<String>, pub status: String, pub quote: String, #[serde(rename = "episodeID")] pub episode_id: String }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Nudge { pub id: String, pub title: String, pub detail: String, #[serde(rename = "personName")] pub person_name: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Promise { pub fact: BrainFact, #[serde(rename = "otherPartyName")] pub other_party_name: Option<String>, #[serde(rename = "iOwe")] pub i_owe: bool }

fn now() -> String { Utc::now().to_rfc3339() }
fn db_path() -> PathBuf { crate::support_root().join("brain.sqlite") }
fn open_db() -> Result<Connection, String> { fs::create_dir_all(crate::support_root()).map_err(|e| e.to_string())?; let connection = Connection::open(db_path()).map_err(|e| e.to_string())?; connection.execute_batch("PRAGMA foreign_keys=ON;").map_err(|e| e.to_string())?; ensure_schema(&connection)?; Ok(connection) }
fn ensure_schema(c: &Connection) -> Result<(), String> {
    c.execute_batch("CREATE TABLE IF NOT EXISTS episodes(id TEXT PRIMARY KEY, meeting_folder TEXT NOT NULL UNIQUE, started_at TEXT NOT NULL, processed_at TEXT, model TEXT); CREATE TABLE IF NOT EXISTS entities(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, name TEXT NOT NULL, world TEXT NOT NULL DEFAULT 'unknown', summary TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, forgotten INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS aliases(entity_id INTEGER NOT NULL REFERENCES entities(id), alias_norm TEXT NOT NULL, alias_display TEXT NOT NULL, source TEXT NOT NULL, PRIMARY KEY(entity_id,alias_norm)); CREATE TABLE IF NOT EXISTS facts(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, subject_id INTEGER REFERENCES entities(id), predicate TEXT NOT NULL, object_id INTEGER REFERENCES entities(id), value TEXT NOT NULL DEFAULT '', owner_id INTEGER REFERENCES entities(id), counterparty_id INTEGER REFERENCES entities(id), due TEXT, done INTEGER NOT NULL DEFAULT 0, valid_from TEXT NOT NULL, invalidated_at TEXT, superseded_by INTEGER REFERENCES facts(id), status TEXT NOT NULL DEFAULT 'verified', confidence REAL NOT NULL DEFAULT 0.0, episode_id TEXT NOT NULL REFERENCES episodes(id), line_start INTEGER NOT NULL DEFAULT 0, line_end INTEGER NOT NULL DEFAULT 0, quote TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, embedding BLOB); CREATE TABLE IF NOT EXISTS episode_entities(episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE, entity_id INTEGER NOT NULL REFERENCES entities(id) ON DELETE CASCADE, PRIMARY KEY(episode_id, entity_id)); CREATE TABLE IF NOT EXISTS person_details(entity_id INTEGER PRIMARY KEY REFERENCES entities(id) ON DELETE CASCADE, include_in_brain INTEGER NOT NULL DEFAULT 1, likes TEXT NOT NULL DEFAULT '[]', dislikes TEXT NOT NULL DEFAULT '[]', family_names TEXT NOT NULL DEFAULT '[]', important_dates TEXT NOT NULL DEFAULT '[]', gift_ideas TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL, notes TEXT NOT NULL DEFAULT ''); PRAGMA user_version=4;").map_err(|e| e.to_string())?;
    let _ = c.execute("ALTER TABLE entities ADD COLUMN closeness_level INTEGER", []);
    let _ = c.execute("ALTER TABLE person_details ADD COLUMN notes TEXT NOT NULL DEFAULT ''", []);
    Ok(())
}
fn parse_world(raw: &str) -> &'static str { match raw.trim().to_lowercase().as_str() { "friend" => "friend", "family" => "family", "business" | "client" | "opposing" | "court" | "team" => "business", "mentor" | "advisor" | "coach" => "mentor", "mentee" | "student" | "protege" | "protégé" => "mentee", "other" => "other", "personal" => "friend", _ => "unknown" } }
fn decode_vec(value: String) -> Vec<String> { serde_json::from_str(&value).unwrap_or_default() }
fn encode_vec(value: &[String]) -> Result<String, String> { serde_json::to_string(value).map_err(|e| e.to_string()) }
fn entity_row(row: &rusqlite::Row<'_>) -> rusqlite::Result<BrainPerson> { Ok(BrainPerson { id: row.get(0)?, kind: row.get(1)?, name: row.get(2)?, world: parse_world(&row.get::<_, String>(3)?).into(), summary: row.get(4)?, created_at: row.get(5)?, updated_at: row.get(6)?, forgotten: row.get::<_, i64>(7)? != 0, closeness_level: row.get(8)? }) }
fn find_entity(c: &Connection, name: &str) -> Result<Option<BrainPerson>, String> { let mut statement = c.prepare("SELECT id,kind,name,world,summary,created_at,updated_at,forgotten,closeness_level FROM entities WHERE kind='person' AND forgotten=0 AND (lower(name)=lower(?) OR id IN (SELECT entity_id FROM aliases WHERE lower(alias_norm)=lower(?))) ORDER BY id LIMIT 1").map_err(|e| e.to_string())?; Ok(statement.query_row(params![name, name], entity_row).optional().map_err(|e| e.to_string())?) }
fn details(c: &Connection, id: i64) -> Result<PersonDetails, String> { let value = c.query_row("SELECT include_in_brain,likes,dislikes,family_names,important_dates,gift_ideas,notes FROM person_details WHERE entity_id=?", [id], |r| Ok(PersonDetails { include_in_brain: r.get::<_, i64>(0)? != 0, likes: decode_vec(r.get(1)?), dislikes: decode_vec(r.get(2)?), family_names: decode_vec(r.get(3)?), important_dates: decode_vec(r.get(4)?), gift_ideas: decode_vec(r.get(5)?), learned: vec![], notes: { let v: String = r.get(6)?; if v.is_empty() { None } else { Some(v) } } })).unwrap_or_default(); Ok(value) }
fn facts_for(c: &Connection, id: i64) -> Result<Vec<BrainFact>, String> { let mut s = c.prepare("SELECT f.id,f.kind,f.predicate,f.value,f.due,f.done,f.valid_from,f.invalidated_at,f.status,f.quote,f.episode_id FROM facts f WHERE f.subject_id=? OR f.object_id=? OR f.owner_id=? OR f.counterparty_id=? ORDER BY f.valid_from DESC").map_err(|e| e.to_string())?; let rows = s.query_map(params![id,id,id,id], |r| Ok(BrainFact { id:r.get(0)?,kind:r.get(1)?,predicate:r.get(2)?,value:r.get(3)?,due:r.get(4)?,done:r.get::<_,i64>(5)? != 0,valid_from:r.get(6)?,invalidated_at:r.get(7)?,status:r.get(8)?,quote:r.get(9)?,episode_id:r.get(10)? })).map_err(|e| e.to_string())?; Ok(rows.filter_map(Result::ok).collect()) }
fn suggested_level(count: i64, last: Option<&str>) -> i64 { let Some(value) = last else { return 5 }; let Ok(date) = DateTime::parse_from_rfc3339(value) else { return 5 }; let days = (Utc::now() - date.with_timezone(&Utc)).num_days().max(0); if days <= 14 && count >= 4 { 1 } else if days <= 30 && count >= 2 { 2 } else if days <= 60 { 3 } else if days <= 120 { 4 } else { 5 } }

pub fn is_person_chat_id(id: &str) -> bool { let path = crate::support_root().join("PersonChats.json"); fs::read_to_string(path).ok().and_then(|v| serde_json::from_str::<HashMap<String, Vec<String>>>(&v).ok()).map(|m| m.values().any(|ids| ids.iter().any(|value| value == id))).unwrap_or(false) }
fn person_chat_map() -> HashMap<String, Vec<String>> { fs::read_to_string(crate::support_root().join("PersonChats.json")).ok().and_then(|v| serde_json::from_str(&v).ok()).unwrap_or_default() }
fn save_person_chat_map(map: &HashMap<String, Vec<String>>) -> Result<(), String> { fs::create_dir_all(crate::support_root()).map_err(|e| e.to_string())?; fs::write(crate::support_root().join("PersonChats.json"), serde_json::to_vec_pretty(map).map_err(|e| e.to_string())?).map_err(|e| e.to_string()) }

#[tauri::command]
pub fn brain_orbit() -> Result<Vec<OrbitEntry>, String> { let c = open_db()?; let mut s = c.prepare("SELECT id,kind,name,world,summary,created_at,updated_at,forgotten,closeness_level FROM entities WHERE kind='person' AND forgotten=0 ORDER BY updated_at DESC,name").map_err(|e| e.to_string())?; let people: Vec<BrainPerson> = s.query_map([], entity_row).map_err(|e| e.to_string())?.filter_map(Result::ok).collect(); people.into_iter().map(|entity| { let count: i64 = c.query_row("SELECT count(*) FROM episode_entities WHERE entity_id=?", [entity.id], |r| r.get(0)).unwrap_or_else(|_| c.query_row("SELECT count(DISTINCT ep.id) FROM episodes ep JOIN facts f ON f.episode_id=ep.id WHERE f.subject_id=? OR f.object_id=? OR f.owner_id=? OR f.counterparty_id=?", params![entity.id,entity.id,entity.id,entity.id], |r| r.get(0)).unwrap_or(0)); let last: Option<String> = c.query_row("SELECT max(started_at) FROM episodes WHERE id IN (SELECT episode_id FROM episode_entities WHERE entity_id=?)", [entity.id], |r| r.get(0)).ok().flatten().or_else(|| c.query_row("SELECT max(ep.started_at) FROM episodes ep JOIN facts f ON f.episode_id=ep.id WHERE f.subject_id=? OR f.object_id=? OR f.owner_id=? OR f.counterparty_id=?", params![entity.id,entity.id,entity.id,entity.id], |r| r.get(0)).ok().flatten()); let all = facts_for(&c, entity.id)?; let open = all.iter().any(|f| f.kind == "commitment" && f.done == false && f.invalidated_at.is_none() && f.status != "forgotten"); let level = entity.closeness_level.unwrap_or_else(|| suggested_level(count, last.as_deref())); Ok(OrbitEntry { entity: entity.clone(), meeting_count: count, last_met: last, has_open_promise: open, has_changed: all.iter().any(|f| f.invalidated_at.is_some()), closeness_level: entity.closeness_level, suggested_closeness_level: level }) }).collect() }

#[tauri::command]
pub fn brain_add_person(name: String, world: String, summary: String, email: String) -> Result<BrainPerson, String> { let c = open_db()?; let clean = name.trim(); if clean.is_empty() { return Err("A person needs a name.".into()) } if let Some(person) = find_entity(&c, clean)? { c.execute("UPDATE entities SET world=?,summary=CASE WHEN ?='' THEN summary ELSE ? END,updated_at=? WHERE id=?", params![parse_world(&world), summary.trim(), summary.trim(), now(), person.id]).map_err(|e| e.to_string())?; return find_entity(&c, clean)?.ok_or_else(|| "Person not found after update.".into()) } let stamp = now(); c.execute("INSERT INTO entities(kind,name,world,summary,created_at,updated_at) VALUES('person',?,?,?,?,?)", params![clean,parse_world(&world),summary.trim(),stamp,stamp]).map_err(|e| e.to_string())?; let id = c.last_insert_rowid(); c.execute("INSERT OR IGNORE INTO aliases(entity_id,alias_norm,alias_display,source) VALUES(?,?,?,'manual')", params![id, clean.to_lowercase(), clean]).map_err(|e| e.to_string())?; if !email.trim().is_empty() { c.execute("INSERT OR IGNORE INTO aliases(entity_id,alias_norm,alias_display,source) VALUES(?,?,?,'manual')", params![id,email.trim().to_lowercase(),email.trim()]).map_err(|e| e.to_string())?; } find_entity(&c, clean)?.ok_or_else(|| "Person could not be created.".into()) }

#[tauri::command]
pub fn brain_person(name: String) -> Result<Option<PersonPage>, String> { let c = open_db()?; let Some(entity) = find_entity(&c, &name)? else { return Ok(None) }; let all = facts_for(&c, entity.id)?; let mut meetings = Vec::new(); let mut statement = c.prepare("SELECT e.id,e.meeting_folder,e.started_at,e.processed_at,e.model FROM episodes e JOIN episode_entities x ON x.episode_id=e.id WHERE x.entity_id=? ORDER BY e.started_at DESC").map_err(|e| e.to_string())?; if let Ok(rows) = statement.query_map([entity.id], |r| Ok(PersonMeeting { id:r.get(0)?,meeting_folder:r.get(1)?,started_at:r.get(2)?,processed_at:r.get(3)?,model:r.get(4)? })) { meetings = rows.filter_map(Result::ok).collect(); } if meetings.is_empty() { let mut s = c.prepare("SELECT DISTINCT e.id,e.meeting_folder,e.started_at,e.processed_at,e.model FROM episodes e JOIN facts f ON f.episode_id=e.id WHERE f.subject_id=? OR f.object_id=? OR f.owner_id=? OR f.counterparty_id=? ORDER BY e.started_at DESC").map_err(|e| e.to_string())?; meetings = s.query_map(params![entity.id,entity.id,entity.id,entity.id], |r| Ok(PersonMeeting { id:r.get(0)?,meeting_folder:r.get(1)?,started_at:r.get(2)?,processed_at:r.get(3)?,model:r.get(4)? })).map_err(|e| e.to_string())?.filter_map(Result::ok).collect(); } let details = details(&c, entity.id)?; let open = all.iter().filter(|f| f.kind == "commitment" && !f.done && f.invalidated_at.is_none() && f.status != "forgotten").cloned().collect(); Ok(Some(PersonPage { entity, details, meetings, open_commitments_by_person: open, open_commitments_to_person: vec![], facts: all })) }

#[tauri::command]
pub fn brain_set_closeness(name: String, level: Option<i64>) -> Result<(), String> { if let Some(value) = level { if !(1..=5).contains(&value) { return Err("Closeness is from 1 to 5.".into()) } } let c = open_db()?; let person = find_entity(&c, &name)?.ok_or("Person not found")?; c.execute("UPDATE entities SET closeness_level=?,updated_at=? WHERE id=?", params![level,now(),person.id]).map_err(|e| e.to_string())?; Ok(()) }

#[tauri::command]
pub fn brain_update_details(name: String, value: PersonDetails) -> Result<(), String> { let c = open_db()?; let person = find_entity(&c, &name)?.ok_or("Person not found")?; c.execute("INSERT INTO person_details(entity_id,include_in_brain,likes,dislikes,family_names,important_dates,gift_ideas,updated_at,notes) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET include_in_brain=excluded.include_in_brain,likes=excluded.likes,dislikes=excluded.dislikes,family_names=excluded.family_names,important_dates=excluded.important_dates,gift_ideas=excluded.gift_ideas,updated_at=excluded.updated_at,notes=excluded.notes", params![person.id, value.include_in_brain as i64,encode_vec(&value.likes)?,encode_vec(&value.dislikes)?,encode_vec(&value.family_names)?,encode_vec(&value.important_dates)?,encode_vec(&value.gift_ideas)?,now(),value.notes.unwrap_or_default()]).map_err(|e| e.to_string())?; Ok(()) }

#[tauri::command]
pub fn brain_forget_person(name: String) -> Result<(), String> { let c = open_db()?; let person = find_entity(&c, &name)?.ok_or("Person not found")?; c.execute("UPDATE facts SET status='forgotten' WHERE subject_id=? OR object_id=? OR owner_id=? OR counterparty_id=?", params![person.id,person.id,person.id,person.id]).map_err(|e| e.to_string())?; c.execute("UPDATE entities SET forgotten=1,updated_at=? WHERE id=?", params![now(),person.id]).map_err(|e| e.to_string())?; Ok(()) }

#[tauri::command]
pub fn brain_nudges() -> Result<Vec<Nudge>, String> { let people = brain_orbit()?; let mut out = Vec::new(); for person in people { let Some(last) = person.last_met.as_deref() else { continue }; let Ok(date) = DateTime::parse_from_rfc3339(last) else { continue }; let days = (Utc::now() - date.with_timezone(&Utc)).num_days(); let level = person.closeness_level.unwrap_or(person.suggested_closeness_level); if (level <= 2 && days >= 30) || (level > 2 && days >= 60) { out.push(Nudge { id: format!("contact-{}-{}",person.entity.id,days / 7), title: format!("Reconnect with {}",person.entity.name), detail: format!("It has been about {} days since you last met.",days), person_name: Some(person.entity.name.clone()) }); } if person.has_open_promise { out.push(Nudge { id: format!("promise-{}",person.entity.id), title: format!("Open promise with {}",person.entity.name), detail: "There is an open promise in the Brain.".to_string(), person_name: Some(person.entity.name.clone()) }); } } Ok(out.into_iter().take(5).collect()) }

#[tauri::command]
pub fn brain_promises() -> Result<Vec<Promise>, String> { let c = open_db()?; let mut s = c.prepare("SELECT f.id,f.kind,f.predicate,f.value,f.due,f.done,f.valid_from,f.invalidated_at,f.status,f.quote,f.episode_id,COALESCE(e.name,''),CASE WHEN f.owner_id IS NOT NULL THEN f.owner_id ELSE f.counterparty_id END FROM facts f LEFT JOIN entities e ON e.id=CASE WHEN f.owner_id IS NOT NULL THEN f.owner_id ELSE f.counterparty_id END WHERE f.kind='commitment' AND f.invalidated_at IS NULL AND f.status <> 'forgotten' ORDER BY f.done,f.valid_from DESC").map_err(|e| e.to_string())?; let rows = s.query_map([], |r| Ok((BrainFact { id:r.get(0)?,kind:r.get(1)?,predicate:r.get(2)?,value:r.get(3)?,due:r.get(4)?,done:r.get::<_,i64>(5)? != 0,valid_from:r.get(6)?,invalidated_at:r.get(7)?,status:r.get(8)?,quote:r.get(9)?,episode_id:r.get(10)? },r.get::<_,String>(11)?))).map_err(|e| e.to_string())?; Ok(rows.filter_map(Result::ok).map(|(fact,other)| Promise { i_owe: false, other_party_name: if other.is_empty(){None}else{Some(other)}, fact }).collect()) }

#[tauri::command]
pub fn person_chat_create(name: String) -> Result<String, String> { let id = uuid::Uuid::new_v4().to_string(); let mut map = person_chat_map(); map.entry(name.trim().to_lowercase()).or_default().push(id.clone()); save_person_chat_map(&map)?; Ok(id) }
#[tauri::command]
pub fn person_chat_ids(name: String) -> Vec<String> { person_chat_map().get(&name.trim().to_lowercase()).cloned().unwrap_or_default() }
#[tauri::command]
pub fn person_chat_delete(name: String, id: String) -> Result<(), String> { let mut map = person_chat_map(); if let Some(ids) = map.get_mut(&name.trim().to_lowercase()) { ids.retain(|v| v != &id); } save_person_chat_map(&map)?; let _ = chat::delete_thread(id); Ok(()) }

fn person_section(name: &str) -> String { let Ok(Some(page)) = brain_person(name.to_string()) else { return format!("\nThis chat is about {}.\n",name) }; let mut value = format!("\nThis chat is about {}, a person in the user's life. He, she or they means {} unless the user says otherwise.\n",name,name); if !page.entity.summary.is_empty() { value.push_str(&format!("Who they are: {}\n",page.entity.summary)); } if let Some(notes) = page.details.notes.filter(|v| !v.is_empty()) { value.push_str(&format!("The user's notes about them: {}\n",notes)); } if !page.details.likes.is_empty() { value.push_str(&format!("Likes: {}\n",page.details.likes.join(", "))); } if !page.details.dislikes.is_empty() { value.push_str(&format!("Dislikes: {}\n",page.details.dislikes.join(", "))); } if !page.details.important_dates.is_empty() { value.push_str(&format!("Dates: {}\n",page.details.important_dates.join(", "))); } if let Some(level) = page.entity.closeness_level { value.push_str(&format!("Closeness: {} of 5 (1 = very close)\n",level)); } value.push_str(&format!("Meetings with them on record: {}\n",page.meetings.len())); value }
fn scoped_reply(app: &tauri::AppHandle, state: &tauri::State<'_, AppState>, id: &str, question: &str, system: String, evidence: String) -> Result<String, String> { let _gate = state.model_gate.lock().map_err(|_| "Model gate lock failed".to_string())?; ensure_engine(&state.engine)?; let (port,style) = { let engine = state.engine.lock().map_err(|_| "Engine lock failed".to_string())?; (engine.port.ok_or("The local model is not running")?,engine.style.clone()) }; let user = format!("Local records:\n{}\n\nUser question: {}\nAnswer first, at most 120 words. Use only these records and say when the answer is not in them.",if evidence.is_empty(){"(none)"}else{&evidence},question); let app = app.clone(); let thread_id = id.to_string(); if style.eq_ignore_ascii_case("inkling") { stream_json(port,"/completion",&serde_json::json!({"prompt":inkling_render(&system,&[ChatTurn{role:"user".into(),text:user}]),"n_predict":500,"temperature":0.2,"seed":7,"stream":true,"stop":["<|end_message|>","<|content_model_end_sampling|>"]}),|piece|{let _=app.emit("chat-delta",serde_json::json!({"threadId":thread_id,"text":piece}));}) } else { stream_json(port,"/v1/chat/completions",&serde_json::json!({"messages":[{"role":"system","content":system},{"role":"user","content":user}],"max_tokens":500,"temperature":0.2,"seed":7,"stream":true,"chat_template_kwargs":{"enable_thinking":false}}),|piece|{let _=app.emit("chat-delta",serde_json::json!({"threadId":thread_id,"text":piece}));}) } }

#[tauri::command(async)]
pub async fn send_person_chat(app: tauri::AppHandle, thread_id: String, person: String, question: String, state: tauri::State<'_, AppState>) -> Result<chat::ChatResult, String> { let question = question.trim().to_string(); let meetings = list_saved_meetings(); let ids = crate::bm25_search(&(question.clone()+" "+&person),&meetings,4).into_iter().map(|x|x.0).collect::<Vec<_>>(); let mut evidence = String::new(); for id in &ids { if let Some(m) = meetings.iter().find(|v| &v.id == id) { evidence.push_str(&format!("### {} ({})\n{}\n{}\n",m.title,m.date,m.notes,m.transcript)); } } let system = format!("You are a private assistant on the user's computer. Nothing they type leaves it. Be direct, helpful and brief. Never invent record details. Cite meetings like [Meeting: Title, date].{}",person_section(&person)); let answer = scoped_reply(&app,&state,&thread_id,&question,system,evidence)?; let mut thread = chat::get_thread(thread_id.clone()).unwrap_or_default(); thread.id = thread_id.clone(); if thread.title == "" { thread.title = question.chars().take(50).collect(); } thread.messages.push(chat::ChatMessage { id:uuid::Uuid::new_v4().to_string(),role:"user".into(),text:question.clone(),sources:vec![],action:None,date:now(),prompt:None,sourceHashes:None }); thread.messages.push(chat::ChatMessage { id:uuid::Uuid::new_v4().to_string(),role:"assistant".into(),text:answer.clone(),sources:ids.clone(),action:None,date:now(),prompt:None,sourceHashes:None }); thread.updated=now(); fs::create_dir_all(chat::chats_root()).map_err(|e|e.to_string())?; fs::write(chat::chats_root().join(format!("{}.json",thread_id)),serde_json::to_vec_pretty(&thread).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?; Ok(chat::ChatResult { answer, sources: ids, status: String::new() }) }

